def lotuswisdom_summary(journeyId, includeSteps=None, stepsLimit=None, includeTagPath=None, includeDomainMovements=None, domainMovementsLimit=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0331000" if __import__("os").path.isdir("./environment_mix/0331000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt): return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _parse_dt(s):
        if s is None: return None
        if isinstance(s, datetime.datetime): return s
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        ts = int(_now.timestamp() * 1000)
        v = ts
        out = []
        for _ in range(10):
            out.append(_CROCK[v & 31])
            v >>= 5
        out = list(reversed(out))
        out += [random.choice(_CROCK) for _ in range(16)]
        return f"{prefix}{''.join(out)}"

    def _log(status, error_code=None):
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                logs.append({
                    "id": _ulid_like("lw_req_"),
                    "endpoint": "lotuswisdom_summary",
                    "status": status,
                    "timestamp": _iso(_now),
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "journey_id": journeyId,
                    **({"error_code": error_code} if error_code else {})
                })
                _save(fname, logs)
                break

    if not isinstance(journeyId, str) or re.match(r"^lw_jny_[0-9A-HJKMNP-TV-Z]{16,}$", journeyId) is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid journeyId format.", field="journeyId")

    def _bool_or_none(v, field):
        if v is None: return None
        if isinstance(v, bool): return v
        raise ValueError(field)

    try:
        includeSteps = _bool_or_none(includeSteps, "includeSteps")
        includeTagPath = _bool_or_none(includeTagPath, "includeTagPath")
        includeDomainMovements = _bool_or_none(includeDomainMovements, "includeDomainMovements")
    except ValueError as e:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid boolean.", field=str(e))

    if stepsLimit is not None:
        if not isinstance(stepsLimit, int) or stepsLimit < 1 or stepsLimit > 200:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid stepsLimit.", field="stepsLimit")
    if domainMovementsLimit is not None:
        if not isinstance(domainMovementsLimit, int) or domainMovementsLimit < 1 or domainMovementsLimit > 200:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid domainMovementsLimit.", field="domainMovementsLimit")

    journeys = _load("journeys.json")
    steps = _load("steps.json")
    domain_movements = _load("domain_movements.json")
    tag_path_nodes = _load("tag_path_nodes.json")

    jny = None
    for j in journeys:
        if j.get("id") == journeyId:
            jny = j
            break
    if jny is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Journey not found.", journeyId=journeyId)

    # reconstruct tag path and domain movements from node/movement tables
    nodes = [n for n in tag_path_nodes if n.get("journey_id") == journeyId]
    nodes.sort(key=lambda x: int(x.get("path_index") or 0))
    reconstructed_tag_path = [n.get("tag") for n in nodes if isinstance(n.get("tag"), str)]

    moves = [m for m in domain_movements if m.get("journey_id") == journeyId]
    moves.sort(key=lambda x: int(x.get("sequence_index") or 0))

    # recompute summary if stale or null
    summary_text = jny.get("summary_text")
    summary_updated_at = _parse_dt(jny.get("summary_updated_at"))
    updated_at = _parse_dt(jny.get("updated_at")) or _now
    stale = (summary_text is None) or (summary_updated_at is None) or (summary_updated_at < updated_at)

    if stale:
        applied_steps = [s for s in steps if s.get("journey_id") == journeyId and s.get("status") == "APPLIED"]
        applied_steps.sort(key=lambda x: int(x.get("step_number") or 0))
        last = applied_steps[-1] if applied_steps else None
        parts = []
        parts.append(f"Journey {journeyId} is {jny.get('status')}.")
        parts.append(f"Progress: step {jny.get('current_step_number')}/{jny.get('total_steps_estimate')}, next_step_needed={jny.get('next_step_needed')}.")
        if reconstructed_tag_path:
            parts.append("Tag path: " + " → ".join(reconstructed_tag_path) + ".")
        elif isinstance(jny.get("tag_path"), list) and jny.get("tag_path"):
            parts.append("Tag path: " + " → ".join([str(t) for t in jny.get("tag_path")]) + ".")
        if moves:
            parts.append(f"Domain movements: {len(moves)}.")
            parts.append(f"Current domain: {moves[-1].get('domain_to')}.")
        elif isinstance(jny.get("domain_state"), dict) and jny["domain_state"].get("current_domain") is not None:
            parts.append(f"Current domain: {jny['domain_state'].get('current_domain')}.")
        if last is not None and isinstance(last.get("content"), str) and last.get("content"):
            excerpt = last["content"].strip()
            if len(excerpt) > 240:
                excerpt = excerpt[:237] + "..."
            parts.append("Latest content excerpt: " + excerpt)
        new_summary = " ".join(parts).strip()

        jny["summary_text"] = new_summary
        jny["summary_updated_at"] = _iso(_now)
        jny["updated_at"] = jny.get("updated_at") or _iso(_now)
        _save("journeys.json", journeys)
        summary_text = new_summary

    resp = {
        "journeyId": journeyId,
        "status": jny.get("status"),
        "currentStepNumber": jny.get("current_step_number"),
        "totalStepsEstimate": jny.get("total_steps_estimate"),
        "nextStepNeeded": jny.get("next_step_needed"),
        "summaryText": jny.get("summary_text"),
        "summaryUpdatedAt": jny.get("summary_updated_at"),
        "tagPath": reconstructed_tag_path,
        "domainMovements": None,
        "steps": None,
    }

    if includeTagPath:
        resp["tagPathNodes"] = nodes

    if includeDomainMovements:
        lim = domainMovementsLimit or 50
        recent = list(reversed(moves))[:lim]
        resp["domainMovements"] = recent

    if includeSteps:
        lim = stepsLimit or 50
        srows = [s for s in steps if s.get("journey_id") == journeyId]
        srows.sort(key=lambda x: (_parse_dt(x.get("created_at")) or _now))
        recent = list(reversed(srows))[:lim]
        resp["steps"] = recent

    _log("ok")
    return resp

def lotuswisdom_journeys(status=None, createdAfter=None, createdBefore=None, updatedAfter=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0331000" if __import__("os").path.isdir("./environment_mix/0331000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt): return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _parse_dt(s, field=None, required=False):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        ts = int(_now.timestamp() * 1000)
        v = ts
        out = []
        for _ in range(10):
            out.append(_CROCK[v & 31])
            v >>= 5
        out = list(reversed(out))
        out += [random.choice(_CROCK) for _ in range(16)]
        return f"{prefix}{''.join(out)}"

    def _log(status_s, error_code=None):
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                logs.append({
                    "id": _ulid_like("lw_req_"),
                    "endpoint": "lotuswisdom_journeys",
                    "status": status_s,
                    "timestamp": _iso(_now),
                    "latency_ms": int((time.time() - _t0) * 1000),
                    **({"error_code": error_code} if error_code else {})
                })
                _save(fname, logs)
                break

    STATUSES = ["IN_PROGRESS", "WISDOM_READY", "CANCELLED"]
    if status is not None and (not isinstance(status, str) or status not in STATUSES):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    ca = _parse_dt(createdAfter)
    if createdAfter is not None and ca is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid createdAfter timestamp.", field="createdAfter")
    cb = _parse_dt(createdBefore)
    if createdBefore is not None and cb is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid createdBefore timestamp.", field="createdBefore")
    ua = _parse_dt(updatedAfter)
    if updatedAfter is not None and ua is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid updatedAfter timestamp.", field="updatedAfter")

    if ca and cb and ca > cb:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")

    # cursor: base64url JSON {"offset": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode(cursor + pad).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor payload.", field="cursor")
            offset = obj["offset"]
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    journeys = _load("journeys.json")

    def _dt(row, key):
        return _parse_dt(row.get(key)) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    filtered = []
    for j in journeys:
        if status is not None and j.get("status") != status:
            continue
        cdt = _parse_dt(j.get("created_at"))
        udt = _parse_dt(j.get("updated_at"))
        if ca and cdt and cdt < ca: 
            continue
        if cb and cdt and cdt >= cb:
            continue
        if ua and udt and udt < ua:
            continue
        filtered.append(j)

    # sort most recently updated first
    filtered.sort(key=lambda r: _dt(r, "updated_at"), reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

