def lotuswisdom_journey_update(journeyId, status, cancelReason=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0331000" if __import__("os").path.isdir("./environment_mix/0331000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "lotuswisdom_journey_update"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, ok, error=None, journey_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lw_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "ok": bool(ok),
            "status_code": int(status_code),
            "journey_id": journey_id,
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(journeyId, str) or not re.match(r"^lw_jny_[0-9A-HJKMNP-TV-Z]{16,}$", journeyId):
        _log(400, False, {"code": "VALIDATION_ERROR", "message": "Invalid journeyId format."}, journey_id=journeyId if isinstance(journeyId, str) else None)
        return _err("VALIDATION_ERROR", "Invalid journeyId format.", field="journeyId")
    if status not in ("IN_PROGRESS", "WISDOM_READY", "CANCELLED"):
        _log(400, False, {"code": "VALIDATION_ERROR", "message": "Invalid status."}, journey_id=journeyId)
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if cancelReason is not None and not isinstance(cancelReason, str):
        _log(400, False, {"code": "VALIDATION_ERROR", "message": "cancelReason must be a string."}, journey_id=journeyId)
        return _err("VALIDATION_ERROR", "cancelReason must be a string.", field="cancelReason")
    if status == "CANCELLED" and cancelReason is not None and len(cancelReason) > 2000:
        _log(400, False, {"code": "VALIDATION_ERROR", "message": "cancelReason too long."}, journey_id=journeyId)
        return _err("VALIDATION_ERROR", "cancelReason too long.", field="cancelReason", max_length=2000)

    # Load journey
    journeys = _load("journeys.json")
    if not isinstance(journeys, list):
        journeys = []
    j = None
    j_idx = None
    for i, row in enumerate(journeys):
        if isinstance(row, dict) and row.get("id") == journeyId:
            j = row
            j_idx = i
            break
    if not j:
        _log(404, False, {"code": "NOT_FOUND", "message": "Journey not found."}, journey_id=journeyId)
        return _err("NOT_FOUND", "Journey not found.", journeyId=journeyId)

    current = j.get("status")
    allowed = {
        "IN_PROGRESS": {"WISDOM_READY", "CANCELLED"},
        "WISDOM_READY": {"CANCELLED"},
        "CANCELLED": set(),
    }
    if current not in allowed:
        _log(409, False, {"code": "CONFLICT", "message": "Journey has invalid persisted status."}, journey_id=journeyId)
        return _err("CONFLICT", "Journey has invalid persisted status.", journeyId=journeyId, persisted_status=current)

    if status == current:
        # Idempotent: no-op but must still be consistent; treat as success with returned resource.
        resp = {
            "journey": j,
            "transition": {"from": current, "to": status, "idempotent": True},
        }
        _log(200, True, journey_id=journeyId)
        return resp

    if status not in allowed[current]:
        _log(409, False, {"code": "INVALID_TRANSITION", "message": f"Cannot transition journey from {current} to {status}."}, journey_id=journeyId)
        return _err("INVALID_TRANSITION", f"Cannot transition journey from {current} to {status}.", from_status=current, to_status=status)

    now = _iso_now()
    # Enforce immutable progression fields: this endpoint only changes status and updated_at; optional cancel note stored in domain_state.
    j["status"] = status
    j["updated_at"] = now
    if status == "CANCELLED" and cancelReason:
        ds = j.get("domain_state")
        if not isinstance(ds, dict):
            ds = {}
        ds["cancel_reason"] = cancelReason
        ds["cancelled_at"] = now
        j["domain_state"] = ds

    # Constraint: updated_at >= created_at
    ca = _parse_dt(j.get("created_at"))
    ua = _parse_dt(j.get("updated_at"))
    if ca and ua and ua < ca:
        j["updated_at"] = j.get("created_at")

    journeys[j_idx] = j
    _save("journeys.json", journeys)

    resp = {
        "journey": j,
        "transition": {"from": current, "to": status, "idempotent": False},
    }
    _log(200, True, journey_id=journeyId)
    return resp

