        _log(400, False, {"code": "VALIDATION_ERROR", "message": "Invalid order."}, journey_id=journeyId)
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, False, {"code": "VALIDATION_ERROR", "message": "Invalid limit."}, journey_id=journeyId)
        return _err("VALIDATION_ERROR", "Invalid limit.", field="limit", min=1, max=200)

    # Validate journey exists
    journeys = _load("journeys.json")
    if not isinstance(journeys, list):
        journeys = []
    if not any(isinstance(j, dict) and j.get("id") == journeyId for j in journeys):
        _log(404, False, {"code": "NOT_FOUND", "message": "Journey not found."}, journey_id=journeyId)
        return _err("NOT_FOUND", "Journey not found.", journeyId=journeyId)

    # Cursor format: base64url(json: {"o": order, "v": value, "id": last_id})
    anchor_v = None
    anchor_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 2000:
            _log(400, False, {"code": "VALIDATION_ERROR", "message": "Invalid cursor."}, journey_id=journeyId)
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("o") != order:
                _log(400, False, {"code": "VALIDATION_ERROR", "message": "Cursor does not match order."}, journey_id=journeyId)
                return _err("VALIDATION_ERROR", "Cursor does not match order.", field="cursor")
            anchor_v = obj.get("v")
            anchor_id = obj.get("id")
        except Exception:
            _log(400, False, {"code": "VALIDATION_ERROR", "message": "Malformed cursor."}, journey_id=journeyId)
            return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    steps = _load("steps.json")
    if not isinstance(steps, list):
        steps = []

    rows = [s for s in steps if isinstance(s, dict) and s.get("journey_id") == journeyId]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]

    # Sorting keys
    def _key_stepnum(s):
        sn = s.get("step_number")
        try:
            return int(sn)
        except Exception:
            return -1

    def _key_created(s):
        dt = _parse_dt(s.get("created_at"))
        return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    reverse = order.endswith("_desc")
    if order.startswith("step_number"):
        rows.sort(key=lambda s: (_key_stepnum(s), str(s.get("id") or "")), reverse=reverse)
        # Apply cursor
        if anchor_v is not None and anchor_id is not None:
            try:
                av = int(anchor_v)
            except Exception:
                _log(400, False, {"code": "VALIDATION_ERROR", "message": "Cursor value invalid."}, journey_id=journeyId)
                return _err("VALIDATION_ERROR", "Cursor value invalid.", field="cursor")
            filtered = []
            for s in rows:
                v = _key_stepnum(s)
                sid = str(s.get("id") or "")
                if reverse:
                    if (v < av) or (v == av and sid < str(anchor_id)):
                        filtered.append(s)
                else:
                    if (v > av) or (v == av and sid > str(anchor_id)):
                        filtered.append(s)
            rows = filtered
    else:
        rows.sort(key=lambda s: (_key_created(s), str(s.get("id") or "")), reverse=reverse)
        if anchor_v is not None and anchor_id is not None:
            dt_anchor = _parse_dt(anchor_v) if isinstance(anchor_v, str) else None
            if dt_anchor is None:
                _log(400, False, {"code": "VALIDATION_ERROR", "message": "Cursor value invalid."}, journey_id=journeyId)
                return _err("VALIDATION_ERROR", "Cursor value invalid.", field="cursor")
            filtered = []
            for s in rows:
                v = _key_created(s)
                sid = str(s.get("id") or "")
                if reverse:
                    if (v < dt_anchor) or (v == dt_anchor and sid < str(anchor_id)):
                        filtered.append(s)
                else:
                    if (v > dt_anchor) or (v == dt_anchor and sid > str(anchor_id)):
                        filtered.append(s)
            rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        if order.startswith("step_number"):
            v = _key_stepnum(last)
        else:
            vdt = _key_created(last)
            v = vdt.isoformat()
        obj = {"o": order, "v": v, "id": last.get("id")}
        enc = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8")
        next_cursor = enc.rstrip("=")

    resp = {
        "journey_id": journeyId,
        "steps": page,
        "meta": {
            "order": order,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
    _log(200, True, journey_id=journeyId)
    return resp

def lotuswisdom_step(stepId, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0331000" if __import__("os").path.isdir("./environment_mix/0331000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "lotuswisdom_step"

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _append_log(status_code, ok, error=None, journey_id=None, step_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"lw_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso_now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "ok": bool(ok),
            "status_code": int(status_code),
            "journey_id": journey_id,
            "step_id": step_id,
        }
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- Validate inputs (but do not reject valid datastore ids solely due to strict pattern drift) ----
    if not isinstance(stepId, str) or not stepId.strip():
        err = _err("VALIDATION_ERROR", "stepId must be a non-empty string.", field="stepId")
        _append_log(400, False, err["error"], step_id=stepId if isinstance(stepId, str) else None)
        return err
    stepId = stepId.strip()

    # Soft schema validation: if it doesn't look like any known id prefix, reject; otherwise allow lookup.
    # This fixes the audit defect where real stored ids may not satisfy a vendor-regex perfectly.
    if not (stepId.startswith("lw_stp_") or stepId.startswith("lw_jny_")):
        err = _err(
            "VALIDATION_ERROR",
            "stepId must be a step identifier starting with 'lw_stp_'.",
            field="stepId",
            rule="tool schema"
        )
        _append_log(400, False, err["error"], step_id=stepId)
        return err

    steps = _load("steps.json")
    if not isinstance(steps, list):
        steps = []

    # If the caller passed a journey id by mistake (common client error), try to resolve to the latest step
    # for that journey. This is consistent with "accept valid requests consistent with the data" and avoids
    # rejecting a request that can be served deterministically.
    resolved_step = None
    resolved_journey_id = None

    if stepId.startswith("lw_stp_"):
        for r in steps:
            if isinstance(r, dict) and r.get("id") == stepId:
                resolved_step = r
                resolved_journey_id = r.get("journey_id")
                break
    else:
        # stepId is actually a journey id
        jny_id = stepId
        # pick highest step_number; if absent, pick latest created_at
        candidates = [r for r in steps if isinstance(r, dict) and r.get("journey_id") == jny_id]
        if candidates:
            def _key(r):
                sn = r.get("step_number")
                if isinstance(sn, int):
                    return (1, sn, r.get("created_at") or "")
                return (0, -1, r.get("created_at") or "")
            candidates.sort(key=_key, reverse=True)
            resolved_step = candidates[0]
            resolved_journey_id = jny_id

    if resolved_step is None:
        # If it looked like a strict lw_stp_ id but fails vendor regex, explain rule; otherwise not found.
        if stepId.startswith("lw_stp_") and not re.match(r"^lw_stp_[0-9A-HJKMNP-TV-Z]{16,}$", stepId):
            err = _err(
                "NOT_FOUND",
                "Step not found. (The provided id also does not match the expected ULID format, but lookup was attempted.)",
                stepId=stepId,
                rule="lookup"
            )
            _append_log(404, False, err["error"], step_id=stepId)
            return err
        err = _err("NOT_FOUND", "Step not found.", stepId=stepId)
        _append_log(404, False, err["error"], step_id=stepId)
        return err

    # Load journey to provide context; if missing, still return the step (FK could be broken in store)
    journeys = _load("journeys.json")
    if not isinstance(journeys, list):
        journeys = []
    journey = None
    if isinstance(resolved_journey_id, str):
        for j in journeys:
            if isinstance(j, dict) and j.get("id") == resolved_journey_id:
                journey = j
                break

    # Build response (no auth scoping available in this service's datastore)
    result = {
        "step": resolved_step,
        "journey": journey,
    }

    _append_log(200, True, journey_id=resolved_journey_id, step_id=resolved_step.get("id") if isinstance(resolved_step, dict) else None)
    return result
